async function createCheckoutSession(lookupKey) {
  try {
    const response = await fetch(STRIPE_CHECKOUT_ENDPOINT, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ lookupKey })
    });
    if (!response.ok) {
      throw new Error(`Failed to create checkout session: ${response.statusText}`);
    }
    const data = await response.json();
    if (data.url) {
      window.location.href = data.url;
    } else {
      throw new Error("No checkout URL returned from server");
    }
  } catch (error) {
    console.error("Checkout error:", error);
    throw error;
  }
}
async function createPortalSession(sessionId) {
  try {
    const response = await fetch(STRIPE_PORTAL_ENDPOINT, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ sessionId })
    });
    if (!response.ok) {
      throw new Error(`Failed to create portal session: ${response.statusText}`);
    }
    const data = await response.json();
    if (data.url) {
      window.location.href = data.url;
    } else {
      throw new Error("No portal URL returned from server");
    }
  } catch (error) {
    console.error("Portal error:", error);
    throw error;
  }
}
